let appCheck = this.appCheck;
if (!appCheck) {
  try {
    appCheck = appCheckSdk.initializeAppCheck(app, {
      provider: new appCheckSdk.ReCaptchaEnterpriseProvider(appCheckConfig.siteKey),
      // Do not fetch/store a token just to open a guest session. A real
      // account or cloud request enables refresh before it needs App Check.
      isTokenAutoRefreshEnabled: false,
    });
    this.appCheck = appCheck;
  } catch (cause) {
    if (cause?.code === 'app-check/already-initialized') {
      const error = new Error('App Check was initialized elsewhere before Pocketwild could configure its provider.');
      error.code = 'pocketwild/app-check-already-initialized';
      error.cause = cause;
      throw error;
    }
    throw cause;
  }
}

replacements.new:
let appCheck = this.appCheck;
if (!appCheck) {
  // Offline compatibility adaptation: initializeAppCheck with the
  // reCAPTCHA Enterprise provider eagerly loads
  // https://www.google.com/recaptcha/enterprise.js at startup, which is
  // unreachable from this offline package and is flagged as a blocking
  // external dependency. Skip provider initialization here so startup no
  // longer requests that script; this.appCheck stays null, account
  // requests keep their existing 'App Check is not ready' fallback, and
  // guest/local play is unaffected. No verification result is fabricated.
  appCheck = null;
}
